/*
 * Migrate REAL data from SQLite (backend/data/election.sqlite) to Supabase.
 * Skips seeded fake students + auto-generated bulk votes.
 *
 * Usage:
 *   1. Get your SERVICE ROLE key: Supabase Dashboard -> Project Settings -> API
 *   2. Run:
 *      SUPABASE_URL=https://lcgcyuikmynermwaktkd.supabase.co SUPABASE_SERVICE_ROLE_KEY=<key> node backend/migrate-to-supabase.js
 *      (PowerShell: $env:SUPABASE_URL="https://..."; $env:SUPABASE_SERVICE_ROLE_KEY="..."; node backend/migrate-to-supabase.js)
 */

const path = require('path');
const crypto = require('crypto');
const sqlite3 = require('sqlite3').verbose();

const SUPABASE_URL = process.env.SUPABASE_URL || 'https://lcgcyuikmynermwaktkd.supabase.co';
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!SERVICE_KEY) {
  console.error('ERROR: Set SUPABASE_SERVICE_ROLE_KEY env var (Supabase Dashboard -> Project Settings -> API -> service_role).');
  process.exit(1);
}

const dbPath = path.join(__dirname, 'data', 'election.sqlite');
const db = new sqlite3.Database(dbPath, sqlite3.OPEN_READONLY, (err) => {
  if (err) {
    console.error('Cannot open SQLite DB at', dbPath, err.message);
    process.exit(1);
  }
});

function hashPassword(password, salt) {
  return crypto.createHmac('sha256', String(salt).toUpperCase()).update(password).digest('hex');
}

const all = (sql, params = []) =>
  new Promise((resolve, reject) => db.all(sql, params, (e, rows) => (e ? reject(e) : resolve(rows || []))));

async function upsert(table, rows, onConflict, chunkSize = 500) {
  let inserted = 0;
  for (let i = 0; i < rows.length; i += chunkSize) {
    const chunk = rows.slice(i, i + chunkSize);
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?on_conflict=${onConflict}`, {
      method: 'POST',
      headers: {
        apikey: SERVICE_KEY,
        Authorization: `Bearer ${SERVICE_KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates',
      },
      body: JSON.stringify(chunk),
    });
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Upsert ${table} rows ${i}-${i + chunk.length} failed (${res.status}): ${text.slice(0, 500)}`);
    }
    inserted += chunk.length;
    console.log(`  ${table}: ${inserted}/${rows.length}`);
  }
  return inserted;
}

const toBool = (v) => v === 1 || v === true || v === 'true' || v === 't';

(async () => {
  console.log('Reading SQLite:', dbPath);

const [candidates, students, votes, details, settings, approvedMatrics] = await Promise.all([
    all('SELECT * FROM candidates'),
    all('SELECT * FROM students'),
    all('SELECT * FROM votes'),
    all('SELECT * FROM vote_details'),
  all('SELECT * FROM approved_matrics').catch(() => []),
    all('SELECT * FROM system_settings'),
  ]);
console.log(`SQLite counts: candidates=${candidates.length} students=${students.length} votes=${votes.length} vote_details=${details.length} settings=${settings.length} approved_matrics=${(approvedMatrics||[]).length}`);

  // ── Filter to REAL data ──
  const TEST_MATRICS = new Set(['U2024/1234567', 'U2023/7654321']);
  const realStudents = students.filter((s) => {
    if (TEST_MATRICS.has(String(s.matricNo).toUpperCase())) return false;
    // Seeded fakes (initial 15k) + bulk-vote fake students all use password 'student2026'
    const seedHash = hashPassword('student2026', s.matricNo);
    return s.password !== seedHash;
  });

  const realVotes = votes.filter((v) => !v.isAutoGenerated && v.isAutoGenerated !== 1);
  const realVoteIds = new Set(realVotes.map((v) => v.id));
  const realDetails = details.filter((d) => realVoteIds.has(d.voteId));

  console.log(`Real-data filter: students ${students.length} -> ${realStudents.length}, votes ${votes.length} -> ${realVotes.length}, vote_details ${details.length} -> ${realDetails.length}`);
  console.log('(bulk_vote_log skipped entirely — it only logs fake bulk additions)');

  // ── Convert SQLite types to Postgres ──
  const pgVotes = realVotes.map((v) => ({
    id: v.id,
    name: v.name,
    matricNo: v.matricNo,
    votedAt: v.votedAt ? String(v.votedAt).replace(' ', 'T') : undefined,
    manualEntry: toBool(v.manualEntry),
    isAutoGenerated: false,
    enteredBy: v.enteredBy || null,
    college: v.college || null,
  }));

  const pgDetails = realDetails.map((d) => ({ id: d.id, voteId: d.voteId, position: d.position, candidateName: d.candidateName }));
  const pgSettings = settings.map((s) => ({ key: s.key, value: String(s.value) }));

  // ── Push in dependency order ──
  console.log('Uploading candidates...');
  await upsert('candidates', candidates, 'id');
  console.log('Uploading students...');
  await upsert('students', realStudents, 'matricNo');
console.log('Uploading approved_matrics...');
await upsert('approved_matrics', (approvedMatrics || []).map((a) => ({ matricNo: a.matricNo, level: a.level })), 'matricNo,level');
  console.log('Uploading system_settings...');
  await upsert('system_settings', pgSettings, 'key');
  console.log('Uploading votes...');
  await upsert('votes', pgVotes, 'matricNo');
  console.log('Uploading vote_details...');
  await upsert('vote_details', pgDetails, 'id');

  console.log('\nDone. Now run this in Supabase SQL Editor to fix auto-increment sequences:');
  console.log("SELECT setval(pg_get_serial_sequence('votes','id'), COALESCE((SELECT MAX(id) FROM votes), 1));");
  console.log("SELECT setval(pg_get_serial_sequence('vote_details','id'), COALESCE((SELECT MAX(id) FROM vote_details), 1));");

  db.close();
})().catch((e) => {
  console.error('Migration failed:', e.message);
  db.close();
  process.exit(1);
});
